const body = $input.first().json.body || {};
const content = body.content || '';
const prompt = `Sen profesyonel bir üniversite sınav hazırlama yapay zekâsısın. Aşağıdaki ders notunu dikkatlice oku ve bu nottan EN AZ 5 ADET çoktan seçmeli (4 seçenekli A, B, C, D) test sorusu üret.\n\nCevabın kesinlikle ve yalnızca şu JSON şemasına uymak zorundadır:\n{\n  "questions": [\n    {\n      "question": "Soru metni?",\n      "options": ["Seçenek 1", "Seçenek 2", "Seçenek 3", "Seçenek 4"],\n      "correct_answer": "Seçeneklerden biriyle birebir aynı doğru metin",\n      "explanation": "Cevabın neden doğru olduğunun kısa pedagojik açıklaması"\n    }\n  ]\n}\n\nDers Notu İçeriği:\n${content}`;

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://ollama:11434/api/generate',
  body: {
    model: 'qwen2.5:3b',
    format: 'json',
    prompt: prompt,
    stream: false
  },
  json: true
});

let parsed = {};
try {
  parsed = JSON.parse(response.response);
} catch (e) {
  parsed = { questions: [] };
}

let questions = parsed.questions || [];
questions = questions.filter(q => q.question && Array.isArray(q.options) && q.options.length >= 2);

return {
  json: {
    success: questions.length > 0,
    count: questions.length,
    questions: questions,
    timestamp: new Date().toISOString()
  }
};
